.mcgee@instructure.com>","tree":{"sha":"88de4a509119953b7111b6bf564c188d17374f8f","url":"https://api.github.com/repos/aianta/odo-canvas-infrastructure/git/trees/88de4a509119953b7111b6bf564c188d17374f8f"},"url":"https://api.github.com/repos/aianta/odo-canvas-infrastructure/git/commits/2497808b7c89c1fca30802ca27be32ab2926c948","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/17241415?v=4","events_url":"https://api.github.com/users/smcgee31/events{/privacy}","followers_url":"https://api.github.com/users/smcgee31/followers","following_url":"https://api.github.com/users/smcgee31/following{/other_user}","gists_url":"https://api.github.com/users/smcgee31/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/smcgee31","id":17241415,"login":"smcgee31","node_id":"MDQ6VXNlcjE3MjQxNDE1","organizations_url":"https://api.github.com/users/smcgee31/orgs","received_events_url":"https://api.github.com/users/smcgee31/received_events","repos_url":"https://api.github.com/users/smcgee31/repos","site_admin":false,"starred_url":"https://api.github.com/users/smcgee31/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/smcgee31/subscriptions","type":"User","url":"https://api.github.com/users/smcgee31","user_view_type":"public"},"html_url":"https://github.com/aianta/odo-canvas-infrastructure/commit/2497808b7c89c1fca30802ca27be32ab2926c948","node_id":"C_kwDOPSThX9oAKDI0OTc4MDhiN2M4OWMxZmNhMzA4MDJjYTI3YmUzMmFiMjkyNmM5NDg","parents":[{"html_url":"https://github.com/aianta/odo-canvas-infrastructure/commit/9d113bcf56c1078e8ffd63f81a8aa3ae9716ba0d","sha":"9d113bcf56c1078e8ffd63f81a8aa3ae9716ba0d","url":"https://api.github.com/repos/aianta/odo-canvas-infrastructure/commits/9d113bcf56c1078e8ffd63f81a8aa3ae9716ba0d"}],"sha":"2497808b7c89c1fca30802ca27be32ab2926c948","url":"https://api.github.com/repos/aianta/odo-canvas-infrastructure/commits/24978